/**
 * Metadata of a brand component (node-safe, no React).
 * Every component has a folder remotion/components/<Name>/ with:
 *   def.ts      – schema (zod), meta, sample   ← read by the pipeline AND Remotion
 *   <Name>.tsx  – the component (export const <Name>)
 *   meta.md     – when to use it / when not (Claude reads it while planning the edit)
 * The registry (defs.ts, registry.tsx) is generated by: npm run gen
 */
export type Layout = 'split' | 'full' | 'overlay';

export type ComponentMeta = {
  /** Default duration in seconds */
  seconds: number;
  /** Minimum on-screen time (rule: media ≥ 5 s) */
  minSeconds?: number;
  /** Allowed layouts in a 16:9 video; the first one is the default.
   *  split = panel on the left (2228×2160 design px) next to the speaker
   *  full  = full frame (3840×2160), speaker hidden
   *  overlay = on top of the speaker (3840×2160, transparent) */
  layouts: Layout[];
  /** Behavior in a 9:16 video:
   *  stage   = card on a light surface (split: graphic on top, speaker below; full: centered)
   *  native  = built for portrait, full frame on `canvas` (e.g. 1080×1920)
   *  overlay = on top of the speaker (2160×3840, transparent)
   *  false   = not for Shorts */
  portrait: 'stage' | 'native' | 'overlay' | false;
  /** Custom design grid, if different (e.g. 1080×1920 for portrait-only blocks) */
  canvas?: { w: number; h: number };
  group: 'Cards' | 'Media' | 'Overlays';
  /** Component needs media files in its props (src …) */
  usesMedia?: boolean;
};
